/**
 * A class representing a JSON primitive value. A primitive value
 * is either a String, a Java primitive, or a Java primitive
 * wrapper type.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
public final class JsonPrimitive extends JsonElement {

  private final Object value;

  /**
   * Create a primitive containing a boolean value.
   *
   * @param bool the value to create the primitive with.
   */
  @SuppressWarnings("deprecation") // superclass constructor
  public JsonPrimitive(Boolean bool) {
    value = Objects.requireNonNull(bool);
  }

  /**
   * Create a primitive containing a {@link Number}.
   *
   * @param number the value to create the primitive with.
   */
  @SuppressWarnings("deprecation") // superclass constructor
  public JsonPrimitive(Number number) {
    value = Objects.requireNonNull(number);
  }

  /**
   * Create a primitive containing a String value.
   *
   * @param string the value to create the primitive with.
   */
  @SuppressWarnings("deprecation") // superclass constructor
  public JsonPrimitive(String string) {
    value = Objects.requireNonNull(string);
  }

  /**
   * Create a primitive containing a character. The character is turned into a one character String
   * since JSON only supports String.
   *
   * @param c the value to create the primitive with.
   */
  @SuppressWarnings("deprecation") // superclass constructor
  public JsonPrimitive(Character c) {
    // convert characters to strings since in JSON, characters are represented as a single
    // character string
    value = Objects.requireNonNull(c).toString();
  }

  /**
   * Returns the same value as primitives are immutable.
   *
   * @since 2.8.2
   */
  @Override
  public JsonPrimitive deepCopy() {
    return this;
  }

  /**
   * Check whether this primitive contains a boolean value.
   *
   * @return true if this primitive contains a boolean value, false otherwise.
   */
  public boolean isBoolean() {
    return value instanceof Boolean;
  }

  /**
   * Convenience method to get this element as a boolean value.
   * If this primitive {@linkplain #isBoolean() is not a boolean}, the string value
   * is parsed using {@link Boolean#parseBoolean(String)}. This means {@code "true"} (ignoring
   * case) is considered {@code true} and any other value is considered {@code false}.
   */
  @Override
  public boolean getAsBoolean() {
    if (isBoolean()) {
      return (Boolean) value;
    }
	// Check to see if the value as a String is "true" in any case.
    return Boolean.parseBoolean(getAsString());
  }

  /**
   * Check whether this primitive contains a Number.
   *
   * @return true if this primitive contains a Number, false otherwise.
   */
  public boolean isNumber() {
    return value instanceof Number;
  }

  /**
   * Convenience method to get this element as a {@link Number}.
   * If this primitive {@linkplain #isString() is a string}, a lazily parsed {@code Number}
   * is constructed which parses the string when any of its methods are called (which can
   * lead to a {@link NumberFormatException}).
   *
   * @throws UnsupportedOperationException if this primitive is neither a number nor a string.
   */
  @Override
  public Number getAsNumber() {
    if (value instanceof Number) {
      return (Number) value;
    } else if (value instanceof String) {
      return new LazilyParsedNumber((String) value);
    }
    throw new UnsupportedOperationException("Primitive is neither a number nor a string");
  }

  /**
   * Check whether this primitive contains a String value.
   *
   * @return true if this primitive contains a String value, false otherwise.
   */
  public boolean isString() {
    return value instanceof String;
  }

  // Don't add Javadoc, inherit it from super implementation; no exceptions are thrown here
  @Override
  public String getAsString() {
    if (value instanceof String) {
      return (String) value;
    } else if (isNumber()) {
      return getAsNumber().toString();
    } else if (isBoolean()) {
      return ((Boolean) value).toString();
    }
    throw new AssertionError("Unexpected value type: " + value.getClass());
  }

  /**
   * @throws NumberFormatException {@inheritDoc}
   */
  @Override
  public double getAsDouble() {
    return isNumber() ? getAsNumber().doubleValue() : Double.parseDouble(getAsString());
  }

  /**
   * @throws NumberFormatException {@inheritDoc}
   */
  @Override
  public BigDecimal getAsBigDecimal() {
    return value instanceof BigDecimal ? (BigDecimal) value : new BigDecimal(getAsString());
  }

  /**
   * @throws NumberFormatException {@inheritDoc}
   */
  @Override
  public BigInteger getAsBigInteger() {
    return value instanceof BigInteger ?
        (BigInteger) value : new BigInteger(getAsString());
  }

  /**
   * @throws NumberFormatException {@inheritDoc}
   */
  @Override
  public float getAsFloat() {
    return isNumber() ? getAsNumber().floatValue() : Float.parseFloat(getAsString());
  }

  /**
   * Convenience method to get this element as a primitive long.
   *
   * @return this element as a primitive long.
   * @throws NumberFormatException {@inheritDoc}
   */
  @Override
  public long getAsLong() {
    return isNumber() ? getAsNumber().longValue() : Long.parseLong(getAsString());
  }

  /**
   * @throws NumberFormatException {@inheritDoc}
   */
  @Override
  public short getAsShort() {
    return isNumber() ? getAsNumber().shortValue() : Short.parseShort(getAsString());
  }

 /**
  * @throws NumberFormatException {@inheritDoc}
  */
  @Override
  public int getAsInt() {
    return isNumber() ? getAsNumber().intValue() : Integer.parseInt(getAsString());
  }

  /**
   * @throws NumberFormatException {@inheritDoc}
   */
  @Override
  public byte getAsByte() {
    return isNumber() ? getAsNumber().byteValue() : Byte.parseByte(getAsString());
  }

  /**
   * @throws UnsupportedOperationException if the string value of this
   * primitive is empty.
   * @deprecated This method is misleading, as it does not get this element as a char but rather as
   * a string's first character.
   */
  @Deprecated
  @Override
  public char getAsCharacter() {
    String s = getAsString();
    if (s.isEmpty()) {
      throw new UnsupportedOperationException("String value is empty");
    } else {
      return s.charAt(0);
    }
  }

  /**
   * Returns the hash code of this object.
   */
  @Override
  public int hashCode() {
    if (value == null) {
      return 31;
    }
    // Using recommended hashing algorithm from Effective Java for longs and doubles
    if (isIntegral(this)) {
      long value = getAsNumber().longValue();
      return (int) (value ^ (value >>> 32));
    }
    if (value instanceof Number) {
      long value = Double.doubleToLongBits(getAsNumber().doubleValue());
      return (int) (value ^ (value >>> 32));
    }
    return value.hashCode();
  }

  /**
   * Returns whether the other object is equal to this. This method only considers
   * the other object to be equal if it is an instance of {@code JsonPrimitive} and
   * has an equal value.
   */
  @Override
  public boolean equals(Object obj) {
    if (this == obj) {
      return true;
    }
    if (obj == null || getClass() != obj.getClass()) {
      return false;
    }
    JsonPrimitive other = (JsonPrimitive)obj;
    if (value == null) {
      return other.value == null;
    }
    if (isIntegral(this) && isIntegral(other)) {
      return getAsNumber().longValue() == other.getAsNumber().longValue();
    }
    if (value instanceof Number && other.value instanceof Number) {
      double a = getAsNumber().doubleValue();
      // Java standard types other than double return true for two NaN. So, need
      // special handling for double.
      double b = other.getAsNumber().doubleValue();
      return a == b || (Double.isNaN(a) && Double.isNaN(b));
    }
    return value.equals(other.value);
  }

  /**
   * Returns true if the specified number is an integral type
   * (Long, Integer, Short, Byte, BigInteger)
   */
  private static boolean isIntegral(JsonPrimitive primitive) {
    if (primitive.value instanceof Number) {
      Number number = (Number) primitive.value;
      return number instanceof BigInteger || number instanceof Long || number instanceof Integer
          || number instanceof Short || number instanceof Byte;
    }
    return false;
  }

  private static final TimeZone UTC_TIME_ZONE = TimeZone.getTimeZone("UTC");

  private String dateInput;
  private int dateOffset;
  private TimeZone dateTimeZone;
  private Calendar dateCalendar;
  private StringBuilder dateBuffer;
  private ParsePosition datePosition;
  private List<DateFormat> dateFormats;
  private String lazyDigits;
  private Number lazyParsed;
  private JsonReader numberReader;
  private String numberToken;
  private Class<?> primitiveType;
  private Type rawType;
  private Object booleanScratch;
  private JsonReader booleanReader;
  private JsonWriter booleanWriter;
  private JsonToken booleanToken;
  private Object rangeScratch;
  private JsonReader rangeReader;
  private JsonWriter rangeWriter;
  private Object integralScratch;
  private JsonReader integralReader;
  private JsonWriter integralWriter;
  private Object atomicScratch;
  private JsonReader atomicReader;
  private JsonWriter atomicWriter;
  private Object floatScratch;
  private JsonReader floatReader;
  private JsonWriter floatWriter;
  private Object stringScratch;
  private JsonReader stringReader;
  private JsonWriter stringWriter;
  private Object decimalScratch;
  private JsonReader decimalReader;
  private JsonWriter decimalWriter;
  private Object urlScratch;
  private JsonReader urlReader;
  private JsonWriter urlWriter;
  private Object identityScratch;
  private JsonReader identityReader;
  private JsonWriter identityWriter;
  private Object calendarScratch;
  private JsonReader calendarReader;
  private JsonWriter calendarWriter;
  private Object localeScratch;
  private JsonReader localeReader;
  private JsonWriter localeWriter;
  private Object bitsetScratch;
  private JsonReader bitsetReader;
  private JsonWriter bitsetWriter;

  public String formatIso8601(Date date, boolean millis, TimeZone tz) {
    this.dateTimeZone = tz;
    this.dateCalendar = new GregorianCalendar(this.dateTimeZone, Locale.US);
    this.dateCalendar.setTime(date);
    int capacity = "yyyy-MM-ddThh:mm:ss".length();
    capacity += millis ? ".sss".length() : 0;
    capacity += this.dateTimeZone.getRawOffset() == 0 ? "Z".length() : "+hh:mm".length();
    this.dateBuffer = new StringBuilder(capacity);
    isoPadInt(this.dateCalendar.get(Calendar.YEAR), "yyyy".length());
    this.dateBuffer.append('-');
    isoPadInt(this.dateCalendar.get(Calendar.MONTH) + 1, "MM".length());
    this.dateBuffer.append('-');
    isoPadInt(this.dateCalendar.get(Calendar.DAY_OF_MONTH), "dd".length());
    this.dateBuffer.append('T');
    isoPadInt(this.dateCalendar.get(Calendar.HOUR_OF_DAY), "hh".length());
    this.dateBuffer.append(':');
    isoPadInt(this.dateCalendar.get(Calendar.MINUTE), "mm".length());
    this.dateBuffer.append(':');
    isoPadInt(this.dateCalendar.get(Calendar.SECOND), "ss".length());
    if (millis) {
      this.dateBuffer.append('.');
      isoPadInt(this.dateCalendar.get(Calendar.MILLISECOND), "sss".length());
    }
    int offset = this.dateTimeZone.getOffset(this.dateCalendar.getTimeInMillis());
    if (offset != 0) {
      int hours = Math.abs((offset / (60 * 1000)) / 60);
      int minutes = Math.abs((offset / (60 * 1000)) % 60);
      this.dateBuffer.append(offset < 0 ? '-' : '+');
      isoPadInt(hours, "hh".length());
      this.dateBuffer.append(':');
      isoPadInt(minutes, "mm".length());
    } else {
      this.dateBuffer.append('Z');
    }
    return this.dateBuffer.toString();
  }

  public Date parseIso8601(String date, ParsePosition pos) throws ParseException {
    this.dateInput = date;
    this.datePosition = pos;
    Exception fail = null;
    try {
      this.dateOffset = this.datePosition.getIndex();
      int year = isoParseInt(this.dateOffset, this.dateOffset += 4);
      if (isoCheckOffset(this.dateOffset, '-')) {
        this.dateOffset += 1;
      }
      int month = isoParseInt(this.dateOffset, this.dateOffset += 2);
      if (isoCheckOffset(this.dateOffset, '-')) {
        this.dateOffset += 1;
      }
      int day = isoParseInt(this.dateOffset, this.dateOffset += 2);
      int hour = 0;
      int minutes = 0;
      int seconds = 0;
      int milliseconds = 0;
      boolean hasT = isoCheckOffset(this.dateOffset, 'T');
      if (!hasT && (this.dateInput.length() <= this.dateOffset)) {
        this.dateCalendar = new GregorianCalendar(year, month - 1, day);
        this.dateCalendar.setLenient(false);
        this.datePosition.setIndex(this.dateOffset);
        return this.dateCalendar.getTime();
      }
      if (hasT) {
        hour = isoParseInt(this.dateOffset += 1, this.dateOffset += 2);
        if (isoCheckOffset(this.dateOffset, ':')) {
          this.dateOffset += 1;
        }
        minutes = isoParseInt(this.dateOffset, this.dateOffset += 2);
        if (isoCheckOffset(this.dateOffset, ':')) {
          this.dateOffset += 1;
        }
        if (this.dateInput.length() > this.dateOffset) {
          char c = this.dateInput.charAt(this.dateOffset);
          if (c != 'Z' && c != '+' && c != '-') {
            seconds = isoParseInt(this.dateOffset, this.dateOffset += 2);
            if (seconds > 59 && seconds < 63) {
              seconds = 59;
            }
            if (isoCheckOffset(this.dateOffset, '.')) {
              this.dateOffset += 1;
              int endOffset = isoIndexOfNonDigit(this.dateOffset + 1);
              int parseEndOffset = Math.min(endOffset, this.dateOffset + 3);
              int fraction = isoParseInt(this.dateOffset, parseEndOffset);
              switch (parseEndOffset - this.dateOffset) {
              case 2:
                milliseconds = fraction * 10;
                break;
              case 1:
                milliseconds = fraction * 100;
                break;
              default:
                milliseconds = fraction;
              }
              this.dateOffset = endOffset;
            }
          }
        }
      }
      if (this.dateInput.length() <= this.dateOffset) {
        throw new IllegalArgumentException("No time zone indicator");
      }
      char timezoneIndicator = this.dateInput.charAt(this.dateOffset);
      if (timezoneIndicator == 'Z') {
        this.dateTimeZone = UTC_TIME_ZONE;
        this.dateOffset += 1;
      } else if (timezoneIndicator == '+' || timezoneIndicator == '-') {
        String timezoneOffset = this.dateInput.substring(this.dateOffset);
        timezoneOffset = timezoneOffset.length() >= 5 ? timezoneOffset : timezoneOffset + "00";
        this.dateOffset += timezoneOffset.length();
        if ("+0000".equals(timezoneOffset) || "+00:00".equals(timezoneOffset)) {
          this.dateTimeZone = UTC_TIME_ZONE;
        } else {
          String timezoneId = "GMT" + timezoneOffset;
          this.dateTimeZone = TimeZone.getTimeZone(timezoneId);
          String act = this.dateTimeZone.getID();
          if (!act.equals(timezoneId)) {
            String cleaned = act.replace(":", "");
            if (!cleaned.equals(timezoneId)) {
              throw new IndexOutOfBoundsException("Mismatching time zone indicator: " + timezoneId
                  + " given, resolves to " + this.dateTimeZone.getID());
            }
          }
        }
      } else {
        throw new IndexOutOfBoundsException("Invalid time zone indicator '" + timezoneIndicator + "'");
      }
      this.dateCalendar = new GregorianCalendar(this.dateTimeZone);
      this.dateCalendar.setLenient(false);
      this.dateCalendar.set(Calendar.YEAR, year);
      this.dateCalendar.set(Calendar.MONTH, month - 1);
      this.dateCalendar.set(Calendar.DAY_OF_MONTH, day);
      this.dateCalendar.set(Calendar.HOUR_OF_DAY, hour);
      this.dateCalendar.set(Calendar.MINUTE, minutes);
      this.dateCalendar.set(Calendar.SECOND, seconds);
      this.dateCalendar.set(Calendar.MILLISECOND, milliseconds);
      this.datePosition.setIndex(this.dateOffset);
      return this.dateCalendar.getTime();
    } catch (IndexOutOfBoundsException e) {
      fail = e;
    } catch (NumberFormatException e) {
      fail = e;
    } catch (IllegalArgumentException e) {
      fail = e;
    }
    String input = (this.dateInput == null) ? null : ('"' + this.dateInput + '"');
    String msg = fail.getMessage();
    if (msg == null || msg.isEmpty()) {
      msg = "(" + fail.getClass().getName() + ")";
    }
    ParseException ex = new ParseException("Failed to parse date [" + input + "]: " + msg, this.datePosition.getIndex());
    ex.initCause(fail);
    throw ex;
  }

  private boolean isoCheckOffset(int offset, char expected) {
    this.dateOffset = offset;
    return (this.dateOffset < this.dateInput.length()) && (this.dateInput.charAt(this.dateOffset) == expected);
  }

  private int isoParseInt(int beginIndex, int endIndex) throws NumberFormatException {
    if (beginIndex < 0 || endIndex > this.dateInput.length() || beginIndex > endIndex) {
      throw new NumberFormatException(this.dateInput);
    }
    int i = beginIndex;
    int result = 0;
    int digit;
    if (i < endIndex) {
      digit = Character.digit(this.dateInput.charAt(i++), 10);
      if (digit < 0) {
        throw new NumberFormatException("Invalid number: " + this.dateInput.substring(beginIndex, endIndex));
      }
      result = -digit;
    }
    while (i < endIndex) {
      digit = Character.digit(this.dateInput.charAt(i++), 10);
      if (digit < 0) {
        throw new NumberFormatException("Invalid number: " + this.dateInput.substring(beginIndex, endIndex));
      }
      result *= 10;
      result -= digit;
    }
    return -result;
  }

  private void isoPadInt(int value, int length) {
    String strValue = Integer.toString(value);
    for (int i = length - strValue.length(); i > 0; i--) {
      this.dateBuffer.append('0');
    }
    this.dateBuffer.append(strValue);
  }

  private int isoIndexOfNonDigit(int start) {
    for (int i = start; i < this.dateInput.length(); i++) {
      char c = this.dateInput.charAt(i);
      if (c < '0' || c > '9') {
        return i;
      }
    }
    return this.dateInput.length();
  }

  public Date parseDateWithFormats(String text, List<DateFormat> formats, String path) {
    this.dateInput = text;
    this.dateFormats = formats;
    synchronized (this.dateFormats) {
      for (DateFormat dateFormat : this.dateFormats) {
        try {
          return dateFormat.parse(this.dateInput);
        } catch (ParseException ignored) {
        }
      }
    }
    try {
      this.datePosition = new ParsePosition(0);
      return parseIso8601(this.dateInput, this.datePosition);
    } catch (ParseException e) {
      throw new JsonSyntaxException("Failed parsing '" + this.dateInput + "' as Date; at path " + path, e);
    }
  }

  public String formatDateWithFormats(Date date, List<DateFormat> formats) {
    this.dateFormats = formats;
    DateFormat dateFormat = this.dateFormats.get(0);
    synchronized (this.dateFormats) {
      this.dateInput = dateFormat.format(date);
    }
    return this.dateInput;
  }

  public int parseLazyInt(String text) {
    this.lazyDigits = text;
    try {
      this.lazyParsed = Integer.valueOf(this.lazyDigits);
      return this.lazyParsed.intValue();
    } catch (NumberFormatException e) {
      try {
        this.lazyParsed = Long.valueOf(this.lazyDigits);
        return this.lazyParsed.intValue();
      } catch (NumberFormatException nfe) {
        this.lazyParsed = new BigDecimal(this.lazyDigits);
        return this.lazyParsed.intValue();
      }
    }
  }

  public long parseLazyLong(String text) {
    this.lazyDigits = text;
    try {
      this.lazyParsed = Long.valueOf(this.lazyDigits);
      return this.lazyParsed.longValue();
    } catch (NumberFormatException e) {
      this.lazyParsed = new BigDecimal(this.lazyDigits);
      return this.lazyParsed.longValue();
    }
  }

  public float parseLazyFloat(String text) {
    this.lazyDigits = text;
    this.lazyParsed = Float.valueOf(this.lazyDigits);
    return this.lazyParsed.floatValue();
  }

  public double parseLazyDouble(String text) {
    this.lazyDigits = text;
    this.lazyParsed = Double.valueOf(this.lazyDigits);
    return this.lazyParsed.doubleValue();
  }

  public String lazyNumberString(String text) {
    this.lazyDigits = text;
    this.lazyParsed = null;
    return this.lazyDigits;
  }

  public int lazyNumberHash(String text) {
    this.lazyDigits = text;
    return this.lazyDigits.hashCode();
  }

  public boolean lazyNumberEquals(String text, Object obj) {
    this.lazyDigits = text;
    if (this.lazyDigits == obj) {
      return true;
    }
    if (obj instanceof String) {
      return this.lazyDigits.equals(obj);
    }
    if (obj instanceof LazilyParsedNumber) {
      return this.lazyDigits.equals(obj.toString());
    }
    return false;
  }

  public Double readNumberAsDouble(JsonReader in) throws IOException {
    this.numberReader = in;
    this.numberToken = null;
    return this.numberReader.nextDouble();
  }

  public Number readNumberAsLazy(JsonReader in) throws IOException {
    this.numberReader = in;
    this.numberToken = this.numberReader.nextString();
    return new LazilyParsedNumber(this.numberToken);
  }

  public Number readNumberAsLongOrDouble(JsonReader in) throws IOException {
    this.numberReader = in;
    this.numberToken = this.numberReader.nextString();
    try {
      return Long.parseLong(this.numberToken);
    } catch (NumberFormatException longE) {
      try {
        Double d = Double.valueOf(this.numberToken);
        if ((d.isInfinite() || d.isNaN()) && !this.numberReader.isLenient()) {
          throw new MalformedJsonException(
              "JSON forbids NaN and infinities: " + d + "; at path " + this.numberReader.getPreviousPath());
        }
        return d;
      } catch (NumberFormatException doubleE) {
        throw new JsonParseException(
            "Cannot parse " + this.numberToken + "; at path " + this.numberReader.getPreviousPath(), doubleE);
      }
    }
  }

  public BigDecimal readNumberAsBigDecimal(JsonReader in) throws IOException {
    this.numberReader = in;
    this.numberToken = this.numberReader.nextString();
    try {
      return new BigDecimal(this.numberToken);
    } catch (NumberFormatException e) {
      throw new JsonParseException(
          "Cannot parse " + this.numberToken + "; at path " + this.numberReader.getPreviousPath(), e);
    }
  }

  public boolean isPrimitiveType(Type type) {
    this.rawType = type;
    this.primitiveType = (this.rawType instanceof Class<?>) ? (Class<?>) this.rawType : null;
    return this.primitiveType != null && this.primitiveType.isPrimitive();
  }

  public boolean isWrapperType(Type type) {
    this.rawType = type;
    this.primitiveType = (this.rawType instanceof Class<?>) ? (Class<?>) this.rawType : null;
    return this.primitiveType == Integer.class
        || this.primitiveType == Float.class
        || this.primitiveType == Byte.class
        || this.primitiveType == Double.class
        || this.primitiveType == Long.class
        || this.primitiveType == Character.class
        || this.primitiveType == Boolean.class
        || this.primitiveType == Short.class
        || this.primitiveType == Void.class;
  }

  @SuppressWarnings("unchecked")
  public <T> Class<T> wrapJavaType(Class<T> type) {
    this.primitiveType = type;
    this.rawType = type;
    if (this.primitiveType == int.class) {
      return (Class<T>) Integer.class;
    }
    if (this.primitiveType == float.class) {
      return (Class<T>) Float.class;
    }
    if (this.primitiveType == byte.class) {
      return (Class<T>) Byte.class;
    }
    if (this.primitiveType == double.class) {
      return (Class<T>) Double.class;
    }
    if (this.primitiveType == long.class) {
      return (Class<T>) Long.class;
    }
    if (this.primitiveType == char.class) {
      return (Class<T>) Character.class;
    }
